      "hunk_id": "H028",
      "decision": "SOL",
      "reason": "SOL preserves both the chill and the belated realization that it was too late."
    },
    {
      "hunk_id": "H029",
      "decision": "SOL",
      "reason": "SOL keeps the sharp sound passing his ear and the immediate loss of sight."
    },
    {
      "hunk_id": "H030",
      "decision": "SOL",
      "reason": "“Bit his lip” matches the source’s action; “clenched his lips” does not."
    },
    {
      "hunk_id": "H031",
      "decision": "SOL",
      "reason": "SOL makes clear that the two comrades had repeatedly saved one another."
    },
    {
      "hunk_id": "H032",
      "decision": "SOL",
      "reason": "SOL preserves the dagger’s fatal placement and its taking Hans’s voice and life."
    },
    {
      "hunk_id": "H033",
      "decision": "SOL",
      "reason": "SOL retains the Hunter laying down the body as his expression darkens."
    },
    {
      "hunk_id": "H034",
      "decision": "BASE",
      "reason": "“Holding off” makes the canyon’s use specifically defensive; the source says it suited fighting a larger force."
    },
    {
      "hunk_id": "H035",
      "decision": "SOL",
      "reason": "“Saw death as martyrdom” preserves the fanatics’ belief in natural English."
    },
    {
      "hunk_id": "H036",
      "decision": "BASE",
      "reason": "BASE preserves the precise beat that the lines were about to crumble; “beginning to crumble” changes the timing."
    },
    {
      "hunk_id": "H037",
      "decision": "BASE",
      "reason": "SOL drops the source’s emphasis that the heat was intense."
    },
    {
      "hunk_id": "H038",
      "decision": "SOL",
      "reason": "“Fierce whistle” conveys the source’s intense piercing sound accompanying the falling fire."
    },
    {
      "hunk_id": "H039",
      "decision": "SOL",
      "reason": "“Fireballs” is a natural rendering of the falling balls of fire."
    },
    {
      "hunk_id": "H040",
      "decision": "SOL",
      "reason": "SOL preserves the open-mouthed spectators and the name flashing through their minds."
    },
    {
      "hunk_id": "H041",
      "decision": "SOL",
      "reason": "SOL keeps Magic Johnson’s reputation, Great Cataclysm record, and display of power in more fluid prose."
    },
    {
      "hunk_id": "H042",
      "decision": "SOL",
      "reason": "The fragment continues the preceding description and retains the spell’s potential to turn the battle."
    },
    {
      "hunk_id": "H043",
      "decision": "SOL",
      "reason": "“With that” preserves the hunters’ hopeful response to the spell without adding a condition."
    },
    {
      "hunk_id": "H044",
      "decision": "SOL",
      "reason": "SOL retains the hunters’ shared certainty."
    },
    {
      "hunk_id": "H045",
      "decision": "BASE",
      "reason": "The source says Magic Johnson could lead them to victory; “surest path” drops that leadership role."
    },
    {
      "hunk_id": "H046",
      "decision": "SOL",
      "reason": "SOL preserves that their confidence lasted until water rose from the barren, sandy landscape."
    },
    {
      "hunk_id": "H047",
      "decision": "SOL",
      "reason": "“Piled upon” preserves the accumulating water spheres and their rise into a tidal wave."
    },
    {
      "hunk_id": "H048",
      "decision": "SOL",
      "reason": "SOL retains the opposing forces mingling and then colliding."
    },
    {
      "hunk_id": "H049",
      "decision": "BASE",
      "reason": "The source says the shockwave shook a space hundreds of meters in radius; SOL shifts that to shaking the air."
    },
    {
      "hunk_id": "H050",
      "decision": "BASE",
      "reason": "The source stammers over “God”; “O God” removes that stammer."
    },
    {
      "hunk_id": "H051",
      "decision": "BASE",
      "reason": "The source describes one person’s scream; SOL changes it to multiple screams."
    },
    {
      "hunk_id": "H052",
      "decision": "SOL",
      "reason": "“Blinded everyone” naturally conveys the steam blocking their view, while keeping Magic Johnson’s understanding."
    },
    {
      "hunk_id": "H053",
      "decision": "SOL",
      "reason": "The clipped thought preserves that the spell was blocked almost completely."
    },
    {
      "hunk_id": "H054",
      "decision": "SOL",
      "reason": "SOL preserves the partial damage to the fanatics and the unexpectedly low overall casualties."
    },
    {
      "hunk_id": "H055",
      "decision": "SOL",
      "reason": "“Emerging under heavy guard” preserves their appearance under escort in idiomatic prose."
    },
    {
      "hunk_id": "H056",
      "decision": "SOL",
      "reason": "The omitted brow detail is incidental; SOL retains the low turbans, A-rank status, and combat specialization."
    },
    {
      "hunk_id": "H057",
      "decision": "SOL",
      "reason": "“Built the force” naturally conveys creating the overwhelming military strength before him."
    },
    {
      "hunk_id": "H058",
      "decision": "BASE",
      "reason": "The source says nature changed over thirty years; “landscape” narrows that image."
    },
    {
      "hunk_id": "H059",
      "decision": "SOL",
      "reason": "SOL preserves that gathering and training the mages is not the question he wants answered."
    },
    {
      "hunk_id": "H060",
      "decision": "SOL",
      "reason": "“Went to the beginning and end of it all” preserves the scope of his question in natural English."
    },
    {
      "hunk_id": "H061",
      "decision": "SOL",
      "reason": "SOL keeps the question about the Doppelganger’s motive for preparing everything so thoroughly."
    },
    {
      "hunk_id": "H062",
      "decision": "SOL",
      "reason": "The referent remains clear, and the omitted repeated name and “wondering” do not change the source’s meaning."
    },
    {
      "hunk_id": "H063",
      "decision": "SOL",
      "reason": "The contraction change is stylistic; SOL preserves that it had no time to answer."
    },
    {
      "hunk_id": "H064",
      "decision": "BASE",
      "reason": "The source contrasts his wish to chase the Doppelganger with his inability to move; BASE preserves that contrast."
    },
    {
      "hunk_id": "H065",
      "decision": "SOL",
      "reason": "SOL preserves the fanatics’ rigorous training and understanding of the battle’s key objective."
    },
    {
      "hunk_id": "H066",
      "decision": "SOL",
      "reason": "The context identifies the Hunters as the comparison group, and SOL clarifies the tenfold numerical advantage."
    },
    {
      "hunk_id": "H067",
      "decision": "SOL",
      "reason": "SOL makes clear that the fanatics concentrate fire on the Hunters’ strongest forces and commanders."
    },
    {
      "hunk_id": "H068",
      "decision": "SOL",
      "reason": "SOL preserves the relentless, dangerous attacks despite Magic Johnson’s rank as a Grand Mage."
    },
    {
      "hunk_id": "H069",
      "decision": "SOL",
      "reason": "“Much the same position” preserves the Skeleton King’s parallel predicament."
    },
    {
      "hunk_id": "H070",
      "decision": "SOL",
      "reason": "The Bone Sword term is preserved without BASE’s redundant explanation that it is made of bone."
    },
    {
      "hunk_id": "H071",
      "decision": "SOL",
      "reason": "The antecedents remain clear, and SOL preserves the flashes cutting through the falling bodies toward the Skeleton King."
    },
    {
      "hunk_id": "H072",
      "decision": "SOL",
      "reason": "The following hunk supplies the ten-thousand-person scale; this line retains his disbelief at their madness."
    },
    {
      "hunk_id": "H073",
      "decision": "SOL",
      "reason": "The fragment completes H072 by emphasizing that he had never faced so many of them."
    },
    {
      "hunk_id": "H074",
      "decision": "SOL",
      "reason": "The referent remains clear, and SOL keeps the contrast between his power and the overwhelming wave."
    },
    {
      "hunk_id": "H075",
      "decision": "SOL",
      "reason": "SOL preserves humans’ fear of death, his fear of Erasure, and the source’s birth-and-fate comparison."
    },
    {
      "hunk_id": "H076",
      "decision": "SOL",
      "reason": "“These humans” naturally refers to the people before him without changing the question."
    },
    {
      "hunk_id": "H077",
      "decision": "SOL",
      "reason": "The shorter thought preserves the judgment that the fanatics are the real monsters."
    },
    {
      "hunk_id": "H078",
      "decision": "SOL",
      "reason": "The Skeleton King is the clear subject from context, and SOL preserves the escalating numbers and attacks."
    },
    {
      "hunk_id": "H079",
      "decision": "SOL",
      "reason": "SOL preserves the blade cutting through him and the absence of pain."
    },
    {
      "hunk_id": "H080",
      "decision": "SOL",
      "reason": "The present-tense phrasing keeps the sword visibly lodged in his chest as he sighs."
    },
    {
      "hunk_id": "H081",
      "decision": "SOL",
      "reason": "SOL preserves the turned wrist, bone shard, and pierced attacker’s throat."
    },
    {
      "hunk_id": "H082",
      "decision": "BASE",
      "reason": "BASE preserves the source’s pause after he clears space, before the next shape arrives."
    },
    {
      "hunk_id": "H083",
      "decision": "SOL",
      "reason": "The Skeleton King is the clear subject, and SOL preserves the incoming shape and hurried catch."
    },
    {
      "hunk_id": "H084",
      "decision": "SOL",
      "reason": "SOL retains that the human is alive and coughing blood."
    },
    {
      "hunk_id": "H085",
      "decision": "SOL",
      "reason": "“One he knew” preserves the recognition in concise prose."
    },
    {
      "hunk_id": "H086",
      "decision": "SOL",
      "reason": "The recognition is clear from context, and SOL preserves that blood does not prevent identifying him."
    },
    {
      "hunk_id": "H087",
      "decision": "SOL",
      "reason": "SOL preserves the Skeleton King raising an undead monster with dwindling magical power."
    },
    {
      "hunk_id": "H088",
      "decision": "BASE",
      "reason": "“All looks” suggests handsomeness; the source teases him about having a good physique and little else."
    },
    {
      "hunk_id": "H089",
      "decision": "BASE",
      "reason": "“Barely above a whisper” drops the source’s implication that his voice was fading out."
    },
    {
      "hunk_id": "H090",
      "decision": "BASE",
      "reason": "BASE preserves the unfinished “don’t worry…” before the Skeleton King changes course; SOL completes the phrase differently."
    },
    {
      "hunk_id": "H091",
      "decision": "SOL",
      "reason": "SOL keeps the spoken praise with the action in one paragraph and avoids intensifying “remarkably well” into “damn well.”"
    },
    {
      "hunk_id": "H092",
      "decision": "SOL",
      "reason": "The quoted praise is retained in H091."
    },
    {
      "hunk_id": "H093",
      "decision": "SOL",
      "reason": "“In place of an answer” preserves that the aura arrives instead of a reply."
    },
    {
      "hunk_id": "H094",
      "decision": "BASE",
      "reason": "SOL says strands drift down, adding that the hair falls; BASE preserves the source’s image of windblown blond hair."
    },
    {
      "hunk_id": "H095",
      "decision": "SOL",
      "reason": "“That bastard” conveys the source’s contemptuous reference without changing the judgment."
    },
    {
      "hunk_id": "H096",
      "decision": "SOL",
      "reason": "SOL retains the messy hair and cheek wound in natural phrasing."
    },
    {
      "hunk_id": "H097",
      "decision": "SOL",
      "reason": "SOL preserves the Skeleton King’s quiet laugh at the fury in the man’s eyes."
    },
    {
      "hunk_id": "H098",
      "decision": "BASE",
      "reason": "The source insists that Minwoo fought well no matter how the Skeleton King looks at it; SOL’s “No” answers the previous line as a contradiction."
    },
    {
      "hunk_id": "H099",
      "decision": "SOL",
      "reason": "SOL preserves the threat that death will reveal which of them was the demon."
    },
    {
      "hunk_id": "H100",
      "decision": "BASE",
      "reason": "The source tells him to come in quickly; “Come at me” changes it into a challenge to attack."
    }
  ]
}

